package electroblob.wizardry.spell;

import electroblob.wizardry.Wizardry;
import electroblob.wizardry.item.SpellActions;
import electroblob.wizardry.registry.WizardryItems;
import electroblob.wizardry.util.BlockUtils;
import electroblob.wizardry.util.ParticleBuilder;
import electroblob.wizardry.util.ParticleBuilder.Type;
import electroblob.wizardry.util.SpellModifiers;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.EnumParticleTypes;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.util.math.Vec3d;
import net.minecraft.world.World;

public class Banish extends SpellRay {

	public static final String MINIMUM_TELEPORT_DISTANCE = "minimum_teleport_distance";
	public static final String MAXIMUM_TELEPORT_DISTANCE = "maximum_teleport_distance";

	public Banish(){
		super("banish", SpellActions.POINT, false);
		this.addProperties(MINIMUM_TELEPORT_DISTANCE, MAXIMUM_TELEPORT_DISTANCE);
	}

	@Override
	protected boolean onEntityHit(World world, Entity target, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){

		if(target instanceof EntityLivingBase){

			EntityLivingBase entity = (EntityLivingBase)target;

			double minRadius = getProperty(MINIMUM_TELEPORT_DISTANCE).doubleValue();
			double maxRadius = getProperty(MAXIMUM_TELEPORT_DISTANCE).doubleValue();
			double radius = (minRadius + world.rand.nextDouble() * maxRadius-minRadius) * modifiers.get(WizardryItems.blast_upgrade);

			teleport(entity, world, radius);
		}

		return true;
	}

	@Override
	protected boolean onBlockHit(World world, BlockPos pos, EnumFacing side, Vec3d hit, EntityLivingBase caster, Vec3d origin, int ticksInUse, SpellModifiers modifiers){
		return false;
	}

	@Override
	protected boolean onMiss(World world, EntityLivingBase caster, Vec3d origin, Vec3d direction, int ticksInUse, SpellModifiers modifiers){
		return true;
	}

	@Override
	protected void spawnParticle(World world, double x, double y, double z, double vx, double vy, double vz){
		world.spawnParticle(EnumParticleTypes.PORTAL, x, y - 0.5, z, 0, 0, 0);
		ParticleBuilder.create(Type.DARK_MAGIC).pos(x, y, z).clr(0.2f, 0, 0.2f).spawn(world);
	}

	// Extracted as a separate method for external use
	public boolean teleport(EntityLivingBase entity, World world, double radius){

		float angle = world.rand.nextFloat() * (float)Math.PI * 2;

		int x = MathHelper.floor(entity.posX + MathHelper.sin(angle) * radius);
		int z = MathHelper.floor(entity.posZ - MathHelper.cos(angle) * radius);
		Integer y = BlockUtils.getNearestFloor(world,
				new BlockPos(x, (int)entity.posY, z), (int)radius);

		if(world.isRemote){

			for(int i=0; i<10; i++){
				double dx1 = entity.posX;
				double dy1 = entity.posY + entity.height * world.rand.nextFloat();
				double dz1 = entity.posZ;
				world.spawnParticle(EnumParticleTypes.PORTAL, dx1, dy1, dz1, world.rand.nextDouble() - 0.5,
						world.rand.nextDouble() - 0.5, world.rand.nextDouble() - 0.5);
			}

			if(entity instanceof EntityPlayer) Wizardry.proxy.playBlinkEffect((EntityPlayer)entity);
		}

		if(y != null){

			// This means stuff like snow layers is ignored, meaning when on snow-covered ground the target does
			// not teleport 1 block above the ground.
			if(!world.getBlockState(new BlockPos(x, y, z)).getMaterial().blocksMovement()){
				y--;
			}

			if(world.getBlockState(new BlockPos(x, y + 1, z)).getMaterial().blocksMovement()
					|| world.getBlockState(new BlockPos(x, y + 2, z)).getMaterial().blocksMovement()){
				return false;
			}

			if(!world.isRemote){
				entity.setPositionAndUpdate(x + 0.5, y + 1, z + 0.5);
			}

			this.playSound(world, entity, 0, -1, new SpellModifiers());
		}

		return true;
	}

}

public abstract class SpellRay extends Spell {

	/** The distance below the caster's eyes that the bolt particles start from. */
	public static final double Y_OFFSET = 0.25;

	/** The distance between spawned particles. Defaults to 0.85. */
	// 0.85 was chosen to keep it similar to the most common method used previously, which gave an effective spacing of
	// 10/12 = 0.8333 when the spell did not hit anything.
	protected double particleSpacing = 0.85;
	/** The maximum jitter (random position offset) for spawned particles. Defaults to 0.1. */
	protected double particleJitter = 0.1;
	/** The velocity of spawned particles in the direction the caster is aiming, can be negative. Defaults to 0. */
	protected double particleVelocity = 0;
	/** Whether living entities are ignored when raytracing. Defaults to false. */
	protected boolean ignoreLivingEntities = false;
	/** Whether liquids count as blocks when raytracing. Defaults to false. */
	protected boolean hitLiquids = false;
	/** Whether to ignore uncollidable blocks when raytracing. Defaults to true. */
	protected boolean ignoreUncollidables = true;
	/** The aim assist to use when raytracing. Defaults to 0. */
	protected float aimAssist = 0;

	public SpellRay(String name, EnumAction action, boolean isContinuous){
		this(Wizardry.MODID, name, action, isContinuous);
	}

	public SpellRay(String modID, String name, EnumAction action, boolean isContinuous){
		super(modID, name, action, isContinuous);
		this.addProperties(RANGE);
		this.npcSelector((e, o) -> true);
	}

@Override public boolean canBeCastBy(TileEntityDispenser dispenser) { return true; }

// Finally everything in here is standardised and written in a form that's actually readable - it was long overdue!
@Override
public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

	Vec3d look = caster.getLookVec();
	Vec3d origin = new Vec3d(caster.posX, caster.posY + caster.getEyeHeight() - Y_OFFSET, caster.posZ);
	if(!this.isContinuous && world.isRemote && !Wizardry.proxy.isFirstPerson(caster)){
		origin = origin.add(look.scale(1.2));
	}

	if(!shootSpell(world, origin, look, caster, ticksInUse, modifiers)) return false;

	if(casterSwingsArm(world, caster, hand, ticksInUse, modifiers)) caster.swingArm(hand);
	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

@Override
public boolean cast(World world, EntityLiving caster, EnumHand hand, int ticksInUse, EntityLivingBase target, SpellModifiers modifiers){
	// IDEA: Add in an aiming error and trigger onMiss accordingly
	Vec3d origin = new Vec3d(caster.posX, caster.posY + caster.getEyeHeight() - Y_OFFSET, caster.posZ);
	Vec3d targetPos = null;

	if(target != null){

		if(!ignoreLivingEntities || !EntityUtils.isLiving(target)){
			targetPos = new Vec3d(target.posX, target.posY + target.height / 2, target.posZ);

		}else{

			int x = MathHelper.floor(target.posX);
			int y = (int)target.posY - 1; // -1 because we need the block under the target
			int z = MathHelper.floor(target.posZ);
			BlockPos pos = new BlockPos(x, y, z);

			// This works as if the NPC had actually aimed at the floor beneath the target, so it needs to check that
			// the block is not air and (optionally) not a liquid.
			if(!world.isAirBlock(pos) && (!world.getBlockState(pos).getMaterial().isLiquid() || hitLiquids)){
				targetPos = new Vec3d(x + 0.5, y + 1, z + 0.5);
			}
		}
	}

	if(targetPos == null) return false; // If there was nothing to aim at (e.g. snare when the target is in the air)

	if(!shootSpell(world, origin, targetPos.subtract(origin).normalize(), caster, ticksInUse, modifiers)) return false;

	if(casterSwingsArm(world, caster, hand, ticksInUse, modifiers)) caster.swingArm(hand);
	this.playSound(world, caster, ticksInUse, -1, modifiers);
	return true;
}

@Override
public boolean cast(World world, double x, double y, double z, EnumFacing direction, int ticksInUse, int duration, SpellModifiers modifiers){

	Vec3d vec = new Vec3d(direction.getDirectionVec());
	Vec3d origin = new Vec3d(x, y, z);

	if(!shootSpell(world, origin, vec, null, ticksInUse, modifiers)) return false;
	// This MUST be the coordinates of the actual dispenser, so we need to offset it
	this.playSound(world, x - direction.getXOffset(), y - direction.getYOffset(), z - direction.getZOffset(), ticksInUse, duration, modifiers);
	return true;
}

protected double getRange(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, int ticksInUse, SpellModifiers modifiers){
	return getProperty(RANGE).doubleValue() * modifiers.get(WizardryItems.range_upgrade);
}

protected boolean casterSwingsArm(World world, EntityLivingBase caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){
	return !this.isContinuous && this.action == EnumAction.NONE;
}

/** Takes care of the shared stuff for the three casting methods. This is mainly for internal use. */
protected boolean shootSpell(World world, Vec3d origin, Vec3d direction, @Nullable EntityLivingBase caster, int ticksInUse, SpellModifiers modifiers){

	double range = getRange(world, origin, direction, caster, ticksInUse, modifiers);
	Vec3d endpoint = origin.add(direction.scale(range));

	// Change the filter depending on whether living entities are ignored or not
	RayTraceResult rayTrace = RayTracer.rayTrace(world, origin, endpoint, aimAssist, hitLiquids,
			ignoreUncollidables, false, Entity.class, ignoreLivingEntities ? EntityUtils::isLiving
			: RayTracer.ignoreEntityFilter(caster));

	boolean flag = false;

	if(rayTrace != null){
		// Doesn't matter which way round these are, they're mutually exclusive
		if(rayTrace.typeOfHit == RayTraceResult.Type.ENTITY){
			// Do whatever the spell does when it hits an entity
			// FIXME: Some spells (e.g. lightning web) seem to not render when aimed at item frames
			flag = onEntityHit(world, rayTrace.entityHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// If the spell succeeded, clip the particles to the correct distance so they don't go through the entity
			if(flag) range = origin.distanceTo(rayTrace.hitVec);

		}else if(rayTrace.typeOfHit == RayTraceResult.Type.BLOCK){
			// Do whatever the spell does when it hits an block
			flag = onBlockHit(world, rayTrace.getBlockPos(), rayTrace.sideHit, rayTrace.hitVec, caster, origin, ticksInUse, modifiers);
			// Clip the particles to the correct distance so they don't go through the block
			// Unlike with entities, this is done regardless of whether the spell succeeded, since no spells go
			// through blocks (and in fact, even the ray tracer itself doesn't do that)
			range = origin.distanceTo(rayTrace.hitVec);
		}
	}

	// If flag is false, either the spell missed or the relevant entity/block hit method returned false
	if(!flag && !onMiss(world, caster, origin, direction, ticksInUse, modifiers)) return false;

	// Particle spawning
	if(world.isRemote){
		spawnParticleRay(world, origin, direction, caster, range);
	}

	return true;
}

public static Integer getNearestSurface(World world, BlockPos pos, EnumFacing direction, int range,
										boolean doubleSided, SurfaceCriteria criteria){

	// This is a neat trick that allows a default 'not found' return value for integers where all possible integer
	// values could, in theory, be returned. The alternative is to use a double and have NaN as the default, but
	// that would introduce extra casting, and since NaN can be calculated with, it could produce strange results
	// when unaccounted for. Using an Integer means it'll immediately throw an NPE instead.
	Integer surface = null;
	int currentBest = Integer.MAX_VALUE;

	for(int i = doubleSided ? -range : 0; i <= range && i < currentBest; i++){ // Now short-circuits for efficiency

		BlockPos testPos = pos.offset(direction, i);

		if(criteria.test(world, testPos, direction)){
			// Because the loop now short-circuits, this must be closer than the previous surface found
			surface = (int)GeometryUtils.component(GeometryUtils.getFaceCentre(testPos, direction), direction.getAxis());
			currentBest = Math.abs(i);
		}
	}

	return surface;
}

/**
 * Finds the nearest floor level in the given direction from the given position,
 * within the range specified. This is a shorthand for
 * {@link BlockUtils#getNearestSurface(World, BlockPos, EnumFacing, int, boolean, SurfaceCriteria)};
 * {@code doubleSided} defaults to true, {@code direction} defaults to {@code EnumFacing.UP}, and
 * {@code criteria} defaults to {@link SurfaceCriteria#COLLIDABLE}.
 */
@Nullable
public static Integer getNearestFloor(World world, BlockPos pos, int range){
	return getNearestSurface(world, pos, EnumFacing.UP, range, true, SurfaceCriteria.COLLIDABLE);
}

public interface SurfaceCriteria {

	/**
	 * Tests whether the inputs define a valid surface according to this set of criteria.
	 * @param world The world in which the surface is to be tested.
	 * @param pos The block coordinates of the inside ('solid' part) of the surface.
	 * @param side The direction in which the surface must face.
	 * @return True if the side {@code side} of the block at {@code pos} in {@code world} is a valid surface
	 * according to this set of criteria, false otherwise.
	 */
	boolean test(World world, BlockPos pos, EnumFacing side);

	/** Returns a {@code SurfaceCriteria} with the opposite arrangement to this one. */
	default SurfaceCriteria flip(){
		return (world, pos, side) -> this.test(world, pos.offset(side), side.getOpposite());
	}

	/** Returns a {@code SurfaceCriteria} based on the given condition, where the inside of the surface satisfies
	 * the condition and the outside does not. */
	static SurfaceCriteria basedOn(BiPredicate<World, BlockPos> condition){
		return (world, pos, side) -> condition.test(world, pos) && !condition.test(world, pos.offset(side));
	}

	/** Returns a {@code SurfaceCriteria} based on the given condition, where the inside of the surface satisfies
	 * the condition and the outside does not. */
	static SurfaceCriteria basedOn(Predicate<IBlockState> condition){
		return (world, pos, side) -> condition.test(world.getBlockState(pos)) && !condition.test(world.getBlockState(pos.offset(side)));
	}

	/** Surface criterion which defines a surface as the boundary between a block that cannot be moved through and
	 * a block that can be moved through. This means the surface can be stood on. */
	SurfaceCriteria COLLIDABLE = basedOn(b -> b.getMaterial().blocksMovement());
